<script lang="ts">import { onMount } from 'svelte';import { api } from '$lib/api';type Item={id:string;sku:string;name:string;unitOfMeasure:string;balance:number};let items:Item[]=[];let loading=true;let error='';onMount(async()=>{try{items=(await api.get<{items:Item[]}>('/api/stock/items')).items}catch(e){error=(e as Error).message}finally{loading=false}})</script>
<svelte:head><title>Tools and stock — Oracle Inventory</title></svelte:head><div class="page"><h1>Tools and stock</h1><p>Quantity-managed stock is separate from tagged Assets. Balances are derived from immutable ledger entries.</p>{#if loading}<section class="panel" role="status">Loading stock…</section>{:else if error}<section class="panel" role="alert">{error}</section>{:else if !items.length}<section class="panel">No stock items are available in your authorized scope.</section>{:else}<section class="panel"><table><caption class="sr-only">Stock catalog</caption><thead><tr><th>SKU</th><th>Item</th><th>Unit</th><th>Balance</th></tr></thead><tbody>{#each items as item}<tr><td>{item.sku}</td><td>{item.name}</td><td>{item.unitOfMeasure}</td><td>{item.balance}</td></tr>{/each}</tbody></table></section>{/if}</div><style>.page{max-width:1000px;margin:auto;padding:32px}.panel{border:1px solid #ddd;border-radius:10px;padding:20px;margin-top:16px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #ddd}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}</style>
